"""Generate tables from measured data; never edit measured numbers."""
import json
import statistics
from pathlib import Path

def main():
    repo=Path(__file__).resolve().parents[2]
    path=repo/"benchmark/results/s0a-probe-overhead.json"
    data=json.loads(path.read_text())
    rows=["# S0a zero-source-change probe cost","",
          "Generated by report_s0a.py. Budget p50 <=100 us / p99 <=250 us is unchanged.",
          "Medians below are across five trial quantiles; worst p99 is also shown.",
          "Counts are native queue items (root + decision spans), not just decisions.",
          "Saturated queue pending records and failed exports are not successful capture.","",
          "| Condition | Mode | Trials meeting budget | Median trial p50 us | Median trial p99 us | Worst p99 us | Accepted | Exported | Full drops | Cooldown drops | Failed exports |",
          "|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|"]
    for condition in ("reachable","unreachable","saturated"):
        for mode in ("60hz","tight"):
            xs=[v for v in data["trials"] if v["condition"]==condition and v["mode"]==mode]
            def total(key):return sum(v["counts"].get(key,0) for v in xs)
            rows.append(f"| {condition} | {mode} | {sum(v['budget_met'] for v in xs)}/5 | "
                f"{statistics.median(v['p50_us'] for v in xs):.2f} | "
                f"{statistics.median(v['p99_us'] for v in xs):.2f} | "
                f"{max(v['p99_us'] for v in xs):.2f} | {total('accepted')} | {total('exported')} | "
                f"{total('drop_full')} | {total('drop_cooldown')} | {total('export_failed')} |")
    rows+=["","## Context and flush (all trial quantiles retained in JSON)","",
           "| Condition | Mode | Median enter p50 us | Worst enter p99 us | Median exit p50 us | Worst exit p99 us | Max explicit flush s |",
           "|---|---|---:|---:|---:|---:|---:|"]
    for condition in ("reachable","unreachable","saturated"):
        for mode in ("60hz","tight"):
            xs=[v for v in data["trials"] if v["condition"]==condition and v["mode"]==mode]
            rows.append(f"| {condition} | {mode} | "
                f"{statistics.median(v['context_enter_p50_us'] for v in xs):.2f} | "
                f"{max(v['context_enter_p99_us'] for v in xs):.2f} | "
                f"{statistics.median(v['context_exit_p50_us'] for v in xs):.2f} | "
                f"{max(v['context_exit_p99_us'] for v in xs):.2f} | "
                f"{max(v['flush_seconds'] for v in xs):.6f} |")
    rows+=["",data["method"],"",
           "Two alternatives are returned by the fixed benchmark target, so probes can observe them.",
           "Ordinary A/B probes cannot infer alternatives or rules hidden inside a function.",
           "The expected saturated flush timeout is injected fault behavior, not an unbounded wait.",
           "Importer/doctor reload metadata was bounded after this run; timed Probe.wrap/Recorder paths were unchanged."]
    path.with_suffix(".md").write_text("\n".join(rows)+"\n",encoding="utf-8")

if __name__=="__main__":main()
